-- 008: web publications as the second corpus (SPEC-018, D-034).
--
-- A publication is not a broadcast segment: different unit, different source, different claim. It lives in its
-- own table so no query can add the two together by accident, and every figure can name its corpus.
--
-- Leaning is stored as data with an explicit editorial provenance, because it is a human judgement that must
-- be revisable and attributable — never generated by a model.

CREATE TABLE IF NOT EXISTS sources (
    source_id   TEXT PRIMARY KEY,
    name_en     TEXT NOT NULL,
    leaning     TEXT NOT NULL CHECK (leaning IN ('pro-government', 'opposition', 'independent')),
    base_url    TEXT NOT NULL,
    access_mode TEXT NOT NULL CHECK (access_mode IN ('full', 'headline', 'archive')),
    kind        TEXT NOT NULL CHECK (kind IN ('rss', 'listing', 'sitemap')),
    listing_url TEXT NOT NULL,
    active      BOOLEAN NOT NULL DEFAULT TRUE,
    leaning_note TEXT
);

CREATE TABLE IF NOT EXISTS publications (
    publication_id TEXT PRIMARY KEY,
    source_id      TEXT NOT NULL REFERENCES sources(source_id),
    url            TEXT NOT NULL,
    title          TEXT NOT NULL,
    published_at   TIMESTAMP,
    programme      TEXT,
    excerpt        TEXT,
    body_hash      TEXT,
    body_chars     INTEGER NOT NULL DEFAULT 0,
    fetched_at     TIMESTAMP NOT NULL,
    UNIQUE (source_id, url)
);

CREATE INDEX IF NOT EXISTS idx_publications_source_date
    ON publications(source_id, published_at DESC);

